import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"A workbench","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/workbench.md","filePath":"patterns/workbench.md"}'),n={name:"patterns/workbench.md"};function i(h,e,s,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="a-workbench" tabindex="-1">A workbench <a class="header-anchor" href="#a-workbench" aria-label="Permalink to &quot;A workbench&quot;">​</a></h1><p>The whole screen of a drawing application: the bar, the layers, the stage with its tools, and the inspector of what is selected.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it once, as the frame of the editor. Pages around the editor, such as a list of documents or the settings, are <a href="./../layout#a-page">pages</a>.</p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><ul><li><a href="./../workbench/shell">Shell</a>, which places the regions and holds the keyboard shortcuts.</li><li>A <a href="./../components/topbar">Topbar</a> in <code>top</code>, with the menu of the application as a <code>MenuModel</code>, the name of the document in the centre and the buttons that show the side regions at the end.</li><li>A <a href="./../components/panel">Panel</a> with a <a href="./../workbench/layer-tree">LayerTree</a> in <code>left</code>.</li><li>The drawing surface in <code>stage</code>: the application&#39;s own element.</li><li>A <a href="./../components/drawbar">Drawbar</a> in <code>bottom</code>, with the tools.</li><li>In <code>right</code>, an <a href="./../workbench/inspector-frame">InspectorFrame</a> with <a href="./../workbench/inspector-section">InspectorSection</a> groups and a <a href="./../workbench/field-list">FieldList</a> for one thing, a <a href="./../workbench/selection-summary">SelectionSummary</a> for several, and a plain panel when nothing is selected.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>The application owns the data: the parts report what the person does (a selection, a rename, a new value) and the application applies it and passes the new state back.</li><li>The side regions stand beside the stage from 64rem, float over it down to 48rem and become sheets below; the application only says whether each is open.</li><li>Every tool and panel has a shortcut, listed by the help key.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pattern-workbench/" title="A workbench" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pattern-workbench/" target="_blank" rel="noopener">A workbench</a></figcaption></figure>',10)])])}const f=a(n,[["render",i]]);export{b as __pageData,f as default};
